   if(!isCurrentUI()||workspaceRef.current.trips!==before.trips||workspaceRef.current.activeId!==before.activeId)throw Error('Your trips changed while this backup was being checked. Please try importing again.');
   if(!result.addedTrips.length)return {addedCount:0,skippedCount:result.skippedCount};
   const nextId=before.activeId||result.activeId||result.trips[0]?.id||'';
   await workspace.changeTrips(current=>{
     if(result.addedTrips.some(added=>current.some(existing=>existing.id===added.id)))throw Error('Your trips changed while importing. Please try again.');
     return [...current,...result.addedTrips];
   },'Trips imported');
