   if(reminders.dismissed.has(key)||reminders.dismissed.has(weatherNoticeKey(weather)))return null;
   return <div className="rain-visit-tag"><span>{risk.exposure==='mixed'?'Partly outdoors':'Outdoors'} · rain {risk.probability}%</span>{!plannerReadOnly&&online&&row.it.fixed===null&&!row.it.flightId&&<button className="text-button" onClick={()=>void previewComfort('rain',row.it.aid)}>Find a drier day</button>}<button className="text-button" onClick={()=>reminders.dismiss(key)}>Keep</button></div>;
