 function statusOf(id:string){const googleId=explorer.results.find(r=>r.place.id===id)?.place.googlePlaceId||(id.startsWith('google-')?id.slice(7):places[id]?.googlePlaceId);const same=(pid:string)=>pid===id||!!googleId&&places[pid]?.googlePlaceId===googleId;const d=trip.days.find(d=>d.items.some(a=>same(a.placeId)));return d?'In '+d.label:trip.ideas.some(same)?'In Ideas':'';}
 function previewGoogle(p:Place){placeData.register(p);setPreview(p.id);setSelected(null);if(mobile){setDialog(null);setMobileView('map');}}
 function withSavedAdmission(result:DiscoveryResult):DiscoveryResult{const stored=Object.values(trip.customPlaces).find(p=>p.id===result.place.id||p.googlePlaceId&&p.googlePlaceId===result.place.googlePlaceId);return stored?.lastEntryMinutes?{...result,place:{...result.place,lastEntryMinutes:stored.lastEntryMinutes}}:result;}
 function selectDiscovery(result:DiscoveryResult){placeData.register(result.place);void explorer.select(result);setPreview(result.place.id);setSelected(null);setDiscovery(true);if(mobile&&dialog!=='insert')setDialog('discover');}
 function backToDiscovery(){explorer.back();setPreview(null);setDiscovery(true);if(mobile)setDialog('discover');}
 function searchMapArea(bounds:SearchBounds){setPreview(null);setSelected(null);setDiscovery(true);void explorer.searchArea(bounds);if(mobile)setDialog('discover');}
 function rememberGoogle(t:Trip,p:Place){t.customPlaces[p.id]=persistableTrip({...t,customPlaces:{...t.customPlaces,[p.id]:p}}).customPlaces[p.id];}
 function saveGoogle(p:Place){placeData.register(p);commit('Saved '+p.name+' to Ideas',t=>{rememberGoogle(t,p);if(!t.ideas.includes(p.id))t.ideas.push(p.id);});}
 async function addGoogle(p:Place,to=currentDayIdx,index?:number,keepBrowsing=true){
   if(readOnly||!trip.days[to])return;
   const existing=statusOf(p.id);if(existing&&existing!=='In Ideas'){notify(p.name+' is already in your itinerary.');return;}
   placeData.register(p);const aid=uid();
   if(!await commit('Added '+p.name+' to '+trip.days[to].label,t=>{
     if(p.googlePlaceId&&!Object.hasOwn(PLACES,p.id))rememberGoogle(t,p);else if(!PLACES[p.id])t.customPlaces[p.id]=p;
     const target=t.days[to],pos=prepareStopInsertion(t,target,index),items=target.items;
     const previous=pos?places[items[pos-1].placeId]:dayStartPlace(target,places);
     items.splice(pos,0,{aid,placeId:p.id,duration:defaultDuration(p),fixed:null,mode:defaultMode(previous,p),note:p.userNotes||''});
     t.ideas=t.ideas.filter(id=>id!==p.id&&(!p.googlePlaceId||places[id]?.googlePlaceId!==p.googlePlaceId));
   }))return;
   setAddTarget(null);
   if(keepBrowsing){setAddedTarget({tripId:trip.id,dayIndex:to,aid,name:p.name});if(mobile&&planningView==='day')setDialog('discover');else setDialog(null);}
   else{setPlanningView('day');setSelected(aid);setDayIdx(to);setPreview(null);setDialog(null);setMobileView('list');}
 }
 function chooseAdd(p:Place){setAddDayIndex(currentDayIdx);setAddTarget({place:p,returnToDiscovery:mobile&&dialog==='discover'});setDialog('add-to-trip');}
 function chooseMove(row:Row){setAddDayIndex(currentDayIdx);setAddTarget({place:row.pl,moveAid:row.it.aid,returnToDiscovery:false});setDialog('add-to-trip');}
 async function finishAdd(to:number,index:number){
   if(!addTarget)return;
   if(addTarget.moveAid){const aid=addTarget.moveAid;if(!trip.days[to])return;if(!await commit('Moved '+addTarget.place.name+' to '+trip.days[to].label,t=>{const fresh=locate(aid,t);if(!fresh||!t.days[to])throw Error('This stop changed. Open it again to move it.');const item=t.days[fresh.d].items.splice(fresh.i,1)[0];const insertion=item.flightId||item.departureForFlightId?Math.max(0,Math.min(index,t.days[to].items.length)):prepareStopInsertion(t,t.days[to],index);t.days[to].items.splice(insertion,0,item);}))return;if(planningView==='day'){setDayIdx(to);setSelected(aid);setMobileView('list');}setDialog(null);setAddTarget(null);}
   else addGoogle(addTarget.place,to,index,true);
 }
 function viewAdded(){if(!addedTarget||addedTarget.tripId!==trip.id)return;setPlanningView('day');pendingReveal.current=addedTarget.aid;setDayIdx(addedTarget.dayIndex);setSelected(addedTarget.aid);setDialog(null);setPreview(null);setMobileView('list');setAddedTarget(null);setToast('');}
 function openEndpoint(endpoint:EndpointSide,index=currentDayIdx){closeImprove();setEndpointDraft(createEndpointDraft(trip,index,endpoint,places));setDialog('endpoint');}
 async function saveEndpoint(){
   if(!endpointDraft)return false;
   const draft=endpointDraft;
   if(!await commit((draft.endpoint==='start'?'Day start':'Day end')+' updated',t=>{
     const p=draft.place;
     if(draft.choice.kind==='place'&&p.id!=='hotel'&&!Object.hasOwn(PLACES,p.id)&&!Object.hasOwn(t.customPlaces,p.id)){
       if(p.googlePlaceId)rememberGoogle(t,p);else t.customPlaces[p.id]=p;
     }
     applyDayEndpoint(t,draft.dayId,draft.endpoint,draft.choice,{startTime:draft.startTime,finishBy:draft.finishBy,timezone:draft.timezone});
   }))return false;
   setDialog(null);setEndpointDraft(null);return true;
 }

 function locatePlace(id:string){closeImprove();setLocating(id);setDialog('location');}
 async function chooseLocation(p:Place){if(!locating)return;if(locating==='__day_start'||locating==='__day_end'){
   placeData.register(p);setEndpointDraft(value=>{
     if(!value)return value;
     const prior=appliedFlightBoundaries(trip,value.dayId).departure;
     const selectedDay=trip.days.find(d=>d.id===value.dayId)!;
     const goal=prior?flightTiming(prior).departureGoalMs:null;
     const minutes=goal!=null?Math.round(dayMinutesAt(goal,tripDayDate(trip.startDate,trip.days.indexOf(selectedDay)),dayTimezone(trip,selectedDay))):null;
     return {...value,choice:{kind:'place',placeId:p.id},place:p,finishBy:value.endpoint==='end'&&minutes!==null&&value.finishBy===minutes?null:value.finishBy};
   });setLocating(null);setDialog('endpoint');return;
 }const old=trip.customPlaces[locating];if(old){p={...p,typical:old.typical||p.typical,...(old.lastEntryMinutes?{lastEntryMinutes:old.lastEntryMinutes}:{}),...(old.userLabel?{userLabel:old.userLabel}:!old.googlePlaceId&&locating!=='hotel'?{userLabel:old.name}:{}),...(old.userNotes!==undefined?{userNotes:old.userNotes}:!old.googlePlaceId&&locating!=='hotel'?{userNotes:old.blurb}:{}),};}placeData.register(p);if(!await commit(locating==='hotel'?'Your stay updated':'Location updated',t=>{if(locating==='hotel'){t.customPlaces.hotel={...persistableTrip({...t,customPlaces:{...t.customPlaces,hotel:{...p,id:'hotel',cat:'custom'}}}).customPlaces.hotel};}else{rememberGoogle(t,p);for(const d of t.days){if(d.startPlaceId===locating)d.startPlaceId=p.id;if(d.endPlaceId===locating)d.endPlaceId=p.id;for(const a of d.items)if(a.placeId===locating)a.placeId=p.id;}for(const f of t.flights??[]){if(f.fromPlaceId===locating)f.fromPlaceId=p.id;if(f.toPlaceId===locating)f.toPlaceId=p.id;}for(const stay of t.stays??[])if(stay.placeId===locating)stay.placeId=p.id;t.ideas=[...new Set(t.ideas.map(id=>id===locating?p.id:id))];if(locating!==p.id)delete t.customPlaces[locating];}}))return;setPreview(null);setDialog(null);setLocating(null);}
 function defaultMode(from:Place|undefined,to:Place):Mode{if(!hasCoordinates(from)||!hasCoordinates(to))return 'walk';const km=Math.hypot((from.lat-to.lat)*111,(from.lng-to.lng)*111*Math.cos(to.lat*Math.PI/180));return km<=1.2?'walk':'transit';}
 function selectActivity(aid:string,fromMap=false){if(improveActive){setSelected(aid);return;}setSelected(aid===selected&&!fromMap&&!mobile?null:aid);setPreview(null);if(mobile&&!fromMap)setDialog('activity');if(!mobile&&fromMap){requestAnimationFrame(()=>Array.from(document.querySelectorAll<HTMLElement>('[data-activity-id]')).find(el=>el.dataset.activityId===aid)?.scrollIntoView({block:'nearest',behavior:'smooth'}));}}
 function handleDrop(event:DragEndEvent){setDragged('');if(plannerReadOnly)return;const a=event.active.data.current,o=event.over?.data.current;if(!a||!o)return;if(o.type==='insertion'){if(a.type==='idea'&&places[a.placeId])void insertPlace(places[a.placeId],o.target);else if(a.type==='activity')void moveToInsertion(a.aid,o.target);return;}if(o.type==='ideas'){if(a.type==='activity')removeActivity(a.aid,true);return;}let targetDay=currentDayIdx,targetIndex=day.items.length;if(o.type==='day'){targetDay=o.dayIdx;targetIndex=trip.days[targetDay].items.length;}else if(o.type==='activity'){const l=locate(o.aid);if(!l)return;targetDay=l.d;targetIndex=l.i;}if(a.type==='idea')addPlace(a.placeId,targetDay,targetIndex);else if(a.type==='activity')moveActivity(a.aid,targetDay,targetIndex);}
 function chooseDay(i:number){setPlanningView('day');setDayIdx(i);setSelected(null);setDialog(null);}
