 function exportTrip(){const clean=publicTrip(trip),exportPlaces=getPlaces(clean);const esc=(v:string)=>v.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));const placeLink=(id:string)=>{const p=exportPlaces[id];return `${esc(p.userLabel||p.name)}${p.googlePlaceId?` · <a href="https://www.google.com/maps/search/?api=1&amp;query=Place&amp;query_place_id=${encodeURIComponent(p.googlePlaceId)}">View location on Google Maps</a>`:''}`;};const sections=clean.days.map(d=>`<section><h2>${esc(d.label+' · '+d.title)}</h2><p>${esc(d.date)} · Start ${formatTime(dayStartTime(d))}${d.finishBy!=null?' · Finish goal '+formatTime(d.finishBy):''}</p><p>Start from ${placeLink(d.startPlaceId||'hotel')} · End at ${placeLink(d.endPlaceId||'hotel')}</p><ol>${d.items.map(a=>{const p=exportPlaces[a.placeId];return `<li><strong>${esc(p.userLabel||p.name)}</strong>${p.googlePlaceId?` · <a href="https://www.google.com/maps/search/?api=1&amp;query=Place&amp;query_place_id=${encodeURIComponent(p.googlePlaceId)}">View place on Google Maps</a>`:''}<p>${a.fixed!==null?'Booked '+formatTime(a.fixed)+' · ':''}${formatDuration(a.duration)} visit · ${modeNames[a.mode]}</p><p>${esc(a.note)}</p></li>`;}).join('')}</ol></section>`).join('');const bookings=`${clean.flights?.length?`<section><h2>Flights</h2>${clean.flights.map(f=>`<h3>${esc([f.airline,f.flightNumber].filter(Boolean).join(' ')||'Flight')}</h3><p>${placeLink(f.fromPlaceId)} → ${placeLink(f.toPlaceId)}</p><p>Departure: ${esc(f.departure.date)} ${esc(f.departure.time||'Time to confirm')} (${esc(f.departure.timezone)})${f.departureTerminal?' · Terminal '+esc(f.departureTerminal):''}</p><p>Arrival: ${esc(f.arrival.date)} ${esc(f.arrival.time||'Time to confirm')} (${esc(f.arrival.timezone)})${f.arrivalTerminal?' · Terminal '+esc(f.arrivalTerminal):''}</p><p>Airport buffer: ${f.airportBufferMinutes??120} min · Arrival buffer: ${f.arrivalBufferMinutes??60} min. Scheduled booking details; check your airline for live updates.</p>`).join('')}</section>`:''}${clean.stays?.length?`<section><h2>Accommodation</h2>${clean.stays.map(stay=>`<h3>${placeLink(stay.placeId)}</h3><p>Check-in: ${esc(stay.checkInDate)} ${esc(stay.checkInTime||'Time to confirm')} · Check-out: ${esc(stay.checkOutDate)} ${esc(stay.checkOutTime||'Time to confirm')}</p><p>${esc(stay.timezone)} time</p>`).join('')}</section>`:''}`;const html=`<!doctype html><html lang="en"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(trip.name)} · Daytrail</title><style>body{font:16px/1.6 system-ui;background:#f5f1ea;color:#1e2726;max-width:760px;margin:40px auto;padding:0 24px}h1{font-size:34px}h2,a{color:#0e6e68}section{background:#fffcf7;border:1px solid #e4ddd1;border-radius:16px;padding:20px 28px;margin:24px 0}li{padding:10px 0}p{margin:4px 0;color:#59625f}@media print{body{margin:0;background:white}section{break-inside:avoid}}</style><body><small>DAYTRAIL · Find your places. Plan your days.</small><h1>${esc(trip.name)}</h1><p>${esc(trip.destination)} · ${esc(trip.startDate)} · ${esc(trip.timezone)}</p><p>Read-only planning copy. Private booking details are omitted. Google places are linked; current place details and journey estimates load in Daytrail.</p>${bookings}${sections}<p>Made with Daytrail</p></body></html>`;const u=URL.createObjectURL(new Blob([html],{type:'text/html'})),a=document.createElement('a');a.href=u;a.download=trip.name.replace(/[^a-z0-9]/gi,'-')+'-daytrail.html';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);notify('Read-only itinerary downloaded');}
 function openBookings(kind?:'flight'|'stay',draft?:Partial<FlightSegment>,target?:BookingFlightTarget,expected?:JourneyExpectation){closeImprove();setBookingInitial({kind,draft,target,expected});setDialog('bookings');}
