 function notFlying(intent:'arrival'|'departure'){const index=intent==='arrival'?0:trip.days.length-1;setPlanningView('day');setDayIdx(index);setSelected(null);setMobileView('list');openEndpoint(intent==='arrival'?'start':'end',index);}
 async function addBagStop(stayId:string,purpose:'drop'|'collect'){const stay=trip.stays?.find(s=>s.id===stayId);if(!stay)return;const aid=uid();if(await commit(purpose==='drop'?'Bag-drop stop added':'Bag-collection stop added',t=>{const target=t.days.find(d=>d.id===day.id);if(!target||target.items.length>=100)throw Error('This day is full. Move a stop before adding another.');const savedStay=t.stays?.find(s=>s.id===stayId);if(!savedStay)throw Error('This stay changed. Open the booking again.');const savedPlaces=getPlaces(t),previous=purpose==='drop'?dayStartPlace(target,savedPlaces):savedPlaces[target.items.at(-1)?.placeId||target.startPlaceId||'hotel'];const inbound=target.items[0]?.mode||target.endMode;const item:Activity={aid,placeId:savedStay.placeId,duration:15,fixed:null,mode:purpose==='drop'&&inbound!=='flight'?inbound:defaultMode(previous,savedPlaces[savedStay.placeId]),note:(purpose==='drop'?'Drop bags':'Collect bags')+' · Confirm luggage storage with your accommodation.'};if(purpose==='drop'){if(target.items[0]&&target.items[0].mode!=='flight')target.items[0].mode=defaultMode(savedPlaces[savedStay.placeId],savedPlaces[target.items[0].placeId]);target.items.unshift(item);}else target.items.push(item);})) {setSelected(aid);pendingReveal.current=aid;if(mobile)setDialog('activity');}}

