 async function changeTransport(targetId:string,mode:Mode){
   if(plannerReadOnly||transportBusyRef.current)return;
   const end=targetId==='end:'+day.id,item=day.items.find(a=>'activity:'+a.aid===targetId);
   if(!end&&!item){notify('This journey changed. Choose its transport again.');return;}
   const position=end?day.items.length:day.items.indexOf(item!);
   const from=position?day.items[position-1].placeId:day.startPlaceId||'hotel',to=end?day.endPlaceId||'hotel':item!.placeId;
   const currentMode=end?day.endMode:item!.mode;
   if(mode===currentMode)return;
   const target={dayId:day.id,targetId},expected:JourneyExpectation={fromPlaceId:from,toPlaceId:to,mode:currentMode,flightId:(end?day.endFlightId:item!.flightId)??null};
   if(mode==='flight'){
     openBookings('flight',{fromPlaceId:from,toPlaceId:to,departure:{date:tripDayDate(trip.startDate,currentDayIdx),time:null,timezone:dayTimezone(trip,day)},arrival:{date:tripDayDate(trip.startDate,currentDayIdx),time:null,timezone:dayTimezone(trip,day)}},target,expected);
     return;
   }
   transportBusyRef.current=true;setTransportBusy(true);
   try{await commit('Transport changed to '+modeNames[mode]+(expected.flightId?' · flight kept in Bookings':''),t=>setJourneyGroundMode(t,target,mode,expected));}
   finally{if(isCurrentUI()){transportBusyRef.current=false;setTransportBusy(false);}}
 }
