 const dayTabs=<div className="day-tabs-bar"><div className="day-tabs" role="tablist" aria-label="Trip days">{trip.days.map((d,i)=><DayTab key={d.id} day={d} index={i} active={i===currentDayIdx} live={i===currentDayIdx?sc:undefined} hoursConflict={i===currentDayIdx?redHoursIds.length>0:(overview.days[d.id]?.hoursConflictCount??0)>0} onClick={()=>chooseDay(i)}/>)}</div>{!readOnly&&<button className="add-day-tab" aria-label="Add days to trip" title={trip.days.length>=MAX_TRIP_DAYS?`${MAX_TRIP_DAYS}-day trip limit`:'Add more days'} disabled={trip.days.length>=MAX_TRIP_DAYS} onClick={openAddDays}><Plus size={18}/><span>Add days</span></button>}</div>;
 function defaultDuration(p:Place){const h=p.typical.match(/^(\d+) h(?: (\d+) min)?$/),m=p.typical.match(/^(\d+) min$/);return Math.max(15,Math.min(1440,h?Number(h[1])*60+Number(h[2]||0):m?Number(m[1]):60));}
 const offlineIdeas=trip.ideas.filter(id=>places[id]&&(explorer.category!=='indoor'||indoorIdea(places[id])));
