 function hoursDetail(row:Row){
   const check=visitChecks.get(row.it.aid);if(!check)return null;const error=visitHours.errors[row.it.placeId];
   const date=visitDateForHours(row,tripDayDate(trip.startDate,currentDayIdx));
   const weekday=new Date(date+'T12:00:00Z').getUTCDay(),cutoff=row.pl.lastEntryMinutes?.[weekday];
   const weekdayLabel=new Date(date+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'long',timeZone:'UTC'});
   return <div className={'visit-hours-detail '+(check.status==='closed'||check.status==='short'?'warning':check.status==='unknown'?'unknown':'')}>
     <strong>{visitHours.loading&&!visitHours.infoByPlaceId[row.it.placeId]&&row.pl.googlePlaceId?'Checking visit hours…':check.label}</strong>
     <p>{error?'Opening hours could not load. Your plan is still saved.':check.detail}</p>
     {error&&<button className="text-button" onClick={()=>visitHours.retry(row.it.placeId)}>Retry opening hours</button>}
     {row.pl.googleMapsURI&&<a href={row.pl.googleMapsURI} target="_blank" rel="noopener noreferrer" className="text-button">Check on Google Maps</a>}
     {!plannerReadOnly&&<details className="admission-editor"><summary>{cutoff===undefined?'Add last-entry time':'Last-entry time'} · {weekdayLabel}</summary><p>Use a time confirmed by the venue or your ticket. This applies to {weekdayLabel}s in this trip.</p><form key={row.pl.id+':'+weekday+':'+cutoff} onSubmit={e=>{e.preventDefault();void saveLastEntry(row,String(new FormData(e.currentTarget).get('lastEntry')||''));}}><label>Last entry<input type="time" name="lastEntry" aria-label={'Last entry on '+weekdayLabel} defaultValue={cutoff===undefined?'':formatTime(cutoff)}/></label><button type="submit" className="button small">Save</button>{cutoff!==undefined&&<button type="button" className="text-button" onClick={()=>void saveLastEntry(row,'')}>Clear</button>}</form></details>}
   </div>;
 }
